/**
 * calculatePerformanceRating against member.schack.se's published PERF values.
 *
 * The fixture is generated by `pnpm perf:fixture` (scripts/perf-fixture.mjs) from
 * resultat.schack.se and the JSON API, then frozen — this test is offline.
 */

import { calculatePerformanceRating } from '../../src/utils/eloCalculations';
import fixture from '../fixtures/official-performance.json';

interface Inputs { opponentRatings: number[]; score: number }
interface Entry extends Partial<Inputs> {
  name: string;
  tournamentId: number;
  groupId: number;
  memberId: number;
  official: number;
  mixed?: boolean;
  byType?: Record<string, Inputs>;
}

const entries = fixture.entries as Entry[];

/** Inputs as the official site uses them: a mixed group's games are pooled across rating types. */
function inputsOf(entry: Entry): Inputs {
  if (!entry.mixed) return { opponentRatings: entry.opponentRatings!, score: entry.score! };
  const types = Object.values(entry.byType!);
  return {
    opponentRatings: types.flatMap((t) => t.opponentRatings),
    score: types.reduce((sum, t) => sum + t.score, 0),
  };
}

/** The pre-0.20.1 log formula, frozen here to guard against regressions. */
function legacyPerformance(opponentRatings: number[], score: number): number {
  if (opponentRatings.length === 0) return 0;
  const avg = opponentRatings.reduce((sum, r) => sum + r, 0) / opponentRatings.length;
  const p = score / opponentRatings.length;
  if (p === 1) return Math.round(avg + 800);
  if (p === 0) return Math.round(avg - 800);
  return Math.round(avg - 400 * Math.log10(1 / p - 1));
}

const label = (e: Entry) => `${e.name} [${e.tournamentId}/${e.groupId}/${e.memberId}]`;

describe('calculatePerformanceRating vs member.schack.se', () => {
  it('covers a meaningful sample', () => {
    expect(entries.filter((e) => !e.mixed).length).toBeGreaterThanOrEqual(300);
    expect(new Set(entries.map((e) => e.tournamentId)).size).toBeGreaterThanOrEqual(8);
  });

  it('matches every official value', () => {
    const misses = entries
      .map((e) => {
        const { opponentRatings, score } = inputsOf(e);
        return { e, got: calculatePerformanceRating(opponentRatings, score) };
      })
      .filter(({ e, got }) => got !== e.official)
      .map(({ e, got }) => `${label(e)}: official ${e.official}, got ${got}`);
    expect(misses).toEqual([]);
  });

  it('never breaks a value the legacy formula got right', () => {
    let changed = 0;
    let maxDelta = 0;
    const regressions: string[] = [];
    for (const e of entries) {
      const { opponentRatings, score } = inputsOf(e);
      const legacy = legacyPerformance(opponentRatings, score);
      const now = calculatePerformanceRating(opponentRatings, score);
      if (legacy !== now) {
        changed++;
        maxDelta = Math.max(maxDelta, Math.abs(legacy - now));
      }
      if (legacy === e.official && now !== e.official) regressions.push(label(e));
    }
    console.info(`[officialPerformance] ${changed}/${entries.length} values changed vs the legacy formula, max |Δ| ${maxDelta}`);
    expect(regressions).toEqual([]);
  });
});
